package demo.pharma.security;
import demo.pharma.audit.AuditService; import demo.pharma.common.exception.*; import demo.pharma.employee.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor @PreAuthorize("hasAuthority('SETTINGS_MANAGE')")
public class AccessAdministrationController {private final RoleRepository roles;private final PermissionRepository permissions;private final UserRepository users;private final EmployeeRepository employees;private final PasswordEncoder encoder;private final AuditService audit;
 record PermissionRequest(@NotBlank @Pattern(regexp="[A-Z_]+") String code,@NotBlank String description){}record PermissionView(UUID id,String code,String description){}record RoleRequest(@NotBlank @Pattern(regexp="[A-Z_]+")String name,@NotNull Set<UUID> permissionIds){}record RoleView(UUID id,String name,List<PermissionView> permissions){}record UserRequest(@NotBlank@Size(max=80)String username,@NotBlank@Email String email,@NotBlank@Size(min=8)String password,Set<UUID> roleIds,UUID employeeId){}record UserUpdateRequest(String password,Set<UUID> roleIds,Boolean enabled,Boolean accountLocked,UUID employeeId){}record UserView(UUID id,String username,String email,boolean enabled,boolean accountLocked,UUID employeeId,List<String> roles){}
 @GetMapping("/permissions")List<PermissionView> permissions(){return permissions.findAll().stream().map(this::pv).toList();}@PostMapping("/permissions")@Transactional PermissionView permission(@Valid@RequestBody PermissionRequest r){if(permissions.findByCode(r.code()).isPresent())throw new BusinessException("Permission code already exists");Permission p=permissions.save(new Permission(r.code(),r.description()));audit.logCurrent("PERMISSION_CREATED","PERMISSION",p.getId(),null,p.getCode());return pv(p);}@PutMapping("/permissions/{id}")@Transactional PermissionView permissionUpdate(@PathVariable UUID id,@Valid@RequestBody PermissionRequest r){Permission p=permissions.findById(id).orElseThrow(()->new NotFoundException("Permission",id));p.setCode(r.code());p.setDescription(r.description());permissions.save(p);audit.logCurrent("PERMISSION_UPDATED","PERMISSION",id,null,p.getCode());return pv(p);}
 @GetMapping("/roles")List<RoleView> roles(){return roles.findAll().stream().map(this::rv).toList();}@PostMapping("/roles")@Transactional RoleView role(@Valid@RequestBody RoleRequest r){if(roles.findByName(r.name()).isPresent())throw new BusinessException("Role already exists");Role x=new Role(r.name());x.setPermissions(permissionSet(r.permissionIds()));roles.save(x);audit.logCurrent("ROLE_CREATED","ROLE",x.getId(),null,x.getName());return rv(x);}@PutMapping("/roles/{id}")@Transactional RoleView roleUpdate(@PathVariable UUID id,@Valid@RequestBody RoleRequest r){Role x=roles.findById(id).orElseThrow(()->new NotFoundException("Role",id));x.setName(r.name());x.setPermissions(permissionSet(r.permissionIds()));roles.save(x);audit.logCurrent("ROLE_UPDATED","ROLE",id,null,x.getName());return rv(x);}
 @GetMapping("/users")List<UserView> users(){return users.findAll().stream().map(this::uv).toList();}@PostMapping("/users")@Transactional UserView user(@Valid@RequestBody UserRequest r){if(users.existsByUsernameIgnoreCase(r.username()))throw new BusinessException("Username already exists");AppUser u=new AppUser();u.setUsername(r.username());u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setRoles(roleSet(r.roleIds()));users.save(u);linkEmployee(u,r.employeeId());audit.logCurrent("USER_CREATED","USER",u.getId(),null,u.getUsername());return uv(u);}@PutMapping("/users/{id}")@Transactional UserView userUpdate(@PathVariable UUID id,@Valid@RequestBody UserUpdateRequest r,Authentication authentication){AppUser u=users.findById(id).orElseThrow(()->new NotFoundException("User",id));if(authentication.getName().equalsIgnoreCase(u.getUsername())&&r.roleIds()!=null)throw new BusinessException("Users cannot change their own roles");if(r.password()!=null&&!r.password().isBlank()){if(r.password().length()<8)throw new BusinessException("Password must be at least 8 characters");u.setPassword(encoder.encode(r.password()));}if(r.roleIds()!=null)u.setRoles(roleSet(r.roleIds()));if(r.enabled()!=null)u.setEnabled(r.enabled());if(r.accountLocked()!=null)u.setAccountLocked(r.accountLocked());users.save(u);if(r.employeeId()!=null)linkEmployee(u,r.employeeId());audit.logCurrent("USER_UPDATED","USER",id,null,u.getUsername());return uv(u);}
 private Set<Permission> permissionSet(Set<UUID> ids){if(ids==null)return new HashSet<>();Set<Permission> r=new HashSet<>(permissions.findAllById(ids));if(r.size()!=ids.size())throw new BusinessException("One or more permissions do not exist");return r;}private Set<Role> roleSet(Set<UUID> ids){if(ids==null)return new HashSet<>();Set<Role> r=new HashSet<>(roles.findAllById(ids));if(r.size()!=ids.size())throw new BusinessException("One or more roles do not exist");return r;}private void linkEmployee(AppUser user,UUID id){if(id==null)return;Employee e=employees.findById(id).orElseThrow(()->new NotFoundException("Employee",id));if(e.getUser()!=null&&!e.getUser().getId().equals(user.getId()))throw new BusinessException("Employee already has a user account");e.setUser(user);employees.save(e);}private PermissionView pv(Permission p){return new PermissionView(p.getId(),p.getCode(),p.getDescription());}private RoleView rv(Role r){return new RoleView(r.getId(),r.getName(),r.getPermissions().stream().map(this::pv).sorted(Comparator.comparing(PermissionView::code)).toList());}private UserView uv(AppUser u){UUID e=employees.findAll().stream().filter(x->x.getUser()!=null&&x.getUser().getId().equals(u.getId())).map(Employee::getId).findFirst().orElse(null);return new UserView(u.getId(),u.getUsername(),u.getEmail(),u.isEnabled(),u.isAccountLocked(),e,u.getRoles().stream().map(Role::getName).sorted().toList());}}
